import java.nio.file.*;
import java.util.*;
public class CombatEntryProbe {
 public static void main(String[]args)throws Exception{
  var fs=Class.forName("zombie.ZomboidFileSystem");Object folder=fs.getField("base").get(fs.getField("instance").get(null));var game=Path.of("F:/SteamLibrary/steamapps/common/ProjectZomboid").toFile().getCanonicalFile();for(String key:new String[]{"absoluteFile","canonicalFile"})folder.getClass().getField(key).set(folder,game);folder.getClass().getField("canonicalUri").set(folder,game.toURI());folder.getClass().getField("lowercaseUri").set(folder,java.net.URI.create(game.toURI().toString().toLowerCase(java.util.Locale.ROOT)));
  var node=Class.forName("zombie.core.skinnedmodel.advancedanimation.AnimNode");var state=Class.forName("zombie.core.skinnedmodel.advancedanimation.AnimState");var vars=Class.forName("zombie.core.skinnedmodel.advancedanimation.AnimationVariableSource");var source=Class.forName("zombie.core.skinnedmodel.advancedanimation.IAnimationVariableSource");var set=vars.getMethod("setVariable",String.class,String.class);var select=state.getMethod("getAnimNodes",source,List.class);var parse=node.getMethod("Parse",String.class);
  Object entry=parse.invoke(null,args[0]);Object idle=parse.invoke(null,game+"/media/AnimSets/player/idle/Idle.xml");if(node.getField("isLooped").getBoolean(entry)||node.getField("earlyTransitionOut").getBoolean(entry)||Math.abs(node.getField("blendOutTime").getFloat(entry)-.3f)>.00001)throw new AssertionError("complete entry playback/fade");
  Object st=state.getConstructor().newInstance(),v=vars.getConstructor().newInstance();state.getMethod("addNode",node).invoke(st,idle);state.getMethod("addNode",node).invoke(st,entry);set.invoke(v,"PerformingAction","ProjectYakuza_DD_StyleEntry");set.invoke(v,"isTurning90","false");set.invoke(v,"isTurningAround","false");List<?> active=(List<?>)select.invoke(st,v,new ArrayList<>());if(active.size()!=1||active.get(0)!=entry)throw new AssertionError("entry selection");
  set.invoke(v,"PerformingAction","");List<?> ended=(List<?>)select.invoke(st,v,new ArrayList<>());if(ended.size()!=1||ended.get(0)!=idle||!node.getField("animName").get(idle).equals("Bob_Idle"))throw new AssertionError("relaxed idle fallback");
  for(String group:new String[]{"aim","aim-strafe"}){
   Object custom=parse.invoke(null,Path.of(args[1],"AnimSets/player",group,"ProjectYakuza_DD_CombatIdle.xml").toString());Object aim=parse.invoke(null,game+"/media/AnimSets/player/aim/aim_1handed.xml");Object aimState=state.getConstructor().newInstance();state.getMethod("addNode",node).invoke(aimState,aim);state.getMethod("addNode",node).invoke(aimState,custom);
   set.invoke(v,"Weapon","1handed");set.invoke(v,"Aim","true");set.invoke(v,"ProjectYakuzaActive","true");set.invoke(v,"ProjectYakuzaStyle","dragon_of_dojima");set.invoke(v,"ProjectYakuzaWeaponProfile","");List<?> aimed=(List<?>)select.invoke(aimState,v,new ArrayList<>());if(aimed.size()!=1||aimed.get(0)!=custom||!node.getField("animName").get(custom).equals("ProjectYakuza_DD_CombatIdleLoop"))throw new AssertionError("previous unarmed RMB idle "+group);
   for(String[] reject:new String[][]{{"ProjectYakuzaActive","false"},{"ProjectYakuzaStyle","other.style"},{"ProjectYakuzaWeaponProfile","bat"}}){set.invoke(v,reject[0],reject[1]);List<?> nativeAim=(List<?>)select.invoke(aimState,v,new ArrayList<>());if(nativeAim.size()!=1||nativeAim.get(0)!=aim)throw new AssertionError("foreign/armed fallback "+Arrays.toString(reject));set.invoke(v,"ProjectYakuzaActive","true");set.invoke(v,"ProjectYakuzaStyle","dragon_of_dojima");set.invoke(v,"ProjectYakuzaWeaponProfile","");}
  }
  System.out.println("PASS native full entry selector/fade, relaxed vanilla idle, restored previous RMB idle in aim/strafe and native foreign/armed fallbacks");
 }
}
